const args = process.argv.slice(2);

if (args.includes('--sheet')) {
    contactSheet({
        clips: CLIPS, outDir: OUT_DIR, prefix: '', cols: 4,
        sheetPath: path.join(OUT_DIR, '_sheet-series.jpg'),
    });
} else {
    await generateClips({
        clips: CLIPS, outDir: OUT_DIR, prefix: '',
        only: args.filter(a => !a.startsWith('-')),
        force: true,   // these all exist and are all damaged
    });
}
